147	{
148	public:
149	    /** Create a fixed joint.
150	     
151	     @param a A is the body to connect.
152	     @param b B is the body to connect.
153	     @param anchr It's the pivot position.
154	     @return A object pointer.
155	     */
156	    static PhysicsJointFixed* construct(PhysicsBody* a, PhysicsBody* b, const Vec2& anchr);
157	
158	    virtual bool createConstraints() override;
159	
160	protected:
161	    PhysicsJointFixed() {}
162	    virtual ~PhysicsJointFixed() {}
163	
164	    Vec2 _anchr;
165	};
