167	/**
168	* @brief A limit joint imposes a maximum distance between the two bodies, as if they were connected by a rope.
169	*/
170	class CC_DLL PhysicsJointLimit : public PhysicsJoint
171	{
172	public:
173	    /** Create a limit joint.
174	     
175	     @param a A is the body to connect.
176	     @param b B is the body to connect.
177	     @param anchr1 Anchr1 is the anchor point on body a.
178	     @param anchr2 Anchr2 is the anchor point on body b.
179	     @return A object pointer.
180	     */
181	    static PhysicsJointLimit* construct(PhysicsBody* a, PhysicsBody* b, const Vec2& anchr1, const Vec2& anchr2);
182	    
183	    /** Create a limit joint.
184	     
185	     @param a A is the body to connect.
186	     @param b B is the body to connect.
187	     @param anchr1 Anchr1 is the anchor point on body a.
188	     @param anchr2 Anchr2 is the anchor point on body b.
189	     @param min Define the allowed min distance of the anchor points.
190	     @param max Define the allowed max distance of the anchor points.
191	     @return A object pointer.
192	     */
193	    static PhysicsJointLimit* construct(PhysicsBody* a, PhysicsBody* b, const Vec2& anchr1, const Vec2& anchr2, float min, float max);
194	
195	    /** Get the anchor point on body a.*/
196	    Vec2 getAnchr1() const;
197	    
198	    /** Set the anchor point on body a.*/
199	    void setAnchr1(const Vec2& anchr1);
200	    
201	    /** Get the anchor point on body b.*/
202	    Vec2 getAnchr2() const;
203	    
204	    /** Set the anchor point on body b.*/
205	    void setAnchr2(const Vec2& anchr2);
206	    
207	    /** Get the allowed min distance of the anchor points.*/
208	    float getMin() const;
209	    /** Set the min distance of the anchor points.*/
210	    void setMin(float min);
211	  
212	    /** Get the allowed max distance of the anchor points.*/
213	    float getMax() const;
214	    /** Set the max distance of the anchor points.*/
215	    void setMax(float max);
216	
217	    virtual bool createConstraints() override;
218	
219	protected:
220	    PhysicsJointLimit() {}
221	    virtual ~PhysicsJointLimit() {}
222	
223	    Vec2 _anchr1;
224	    Vec2 _anchr2;
225	    float _min;
226	    float _max;
227	};
