namespace
{
    const float kPi = 3.14159265358979323846f;

    const int kCircleSegments = 12;
    const float kCircleCenterDotRadius = 1.5f;

    const float kJointAnchorRadius = 2.5f;
    const float kJointRestMarkRadius = 1.5f;
    const float kJointLimitTickSize = 4.0f;
    const int kSpringCoilSegments = 8;
    const float kSpringCoilWidth = 4.0f;

    const float kCenterOfMassRadius = 3.0f;
    const float kSleepIndicatorRadius = 4.0f;
    const int kSleepIndicatorSegments = 8;

    const float kContactNormalMinLength = 4.0f;
    const float kVelocityScale = 0.1f;
    const float kArrowHeadSize = 4.0f;
    const float kMinDrawLength = 0.5f;

    const float kSensorAlphaScale = 0.5f;
    const float kRestingIntensity = 0.35f;
    const float kStaticIntensity = 0.6f;

    const int kDebugDrawLocalZOrder = 1000;

    void expandBounds(const Vec2& point, Vec2& lower, Vec2& upper, bool& valid)
    {
        if (!valid)
        {
            lower = point;
            upper = point;
            valid = true;
            return;
        }

        lower.x = std::min(lower.x, point.x);
        lower.y = std::min(lower.y, point.y);
        upper.x = std::max(upper.x, point.x);
        upper.y = std::max(upper.y, point.y);
    }
}

PhysicsDebugDraw::PhysicsDebugDraw()
: _drawNode(nullptr)
, _initialized(false)
{
    _config.drawShapes = true;
    _config.drawJoints = true;
    _config.drawContacts = false;
    _config.drawBoundingBoxes = false;
    _config.drawCentersOfMass = false;
    _config.drawVelocities = false;
    _config.drawSleepState = false;
    _config.shapeColor = Color4F(0.0f, 1.0f, 0.0f, 0.5f);
    _config.jointColor = Color4F(0.0f, 0.0f, 1.0f, 0.8f);
    _config.contactColor = Color4F(1.0f, 0.0f, 0.0f, 1.0f);
    _config.bbColor = Color4F(1.0f, 1.0f, 0.0f, 0.3f);
    _config.lineWidth = 1.0f;
}

PhysicsDebugDraw::~PhysicsDebugDraw()
{
}

bool PhysicsDebugDraw::init(DrawNode* drawNode)
{
    if (drawNode == nullptr)
    {
        return false;
    }

    // the draw node is owned by the caller, it is only borrowed here
    _drawNode = drawNode;
    _drawNode->setLineWidth(_config.lineWidth);
    _drawNode->setLocalZOrder(kDebugDrawLocalZOrder);
    _initialized = true;

    return true;
}

void PhysicsDebugDraw::setConfig(const PhysicsDebugDrawConfig& config)
{
    _config = config;

    if (_drawNode != nullptr)
    {
        _drawNode->setLineWidth(_config.lineWidth);
    }
}

PhysicsDebugDrawConfig PhysicsDebugDraw::getConfig() const
{
    return _config;
}

void PhysicsDebugDraw::beginDraw()
{
    if (_drawNode == nullptr)
    {
        return;
    }

    _drawNode->clear();
    _drawNode->setLineWidth(_config.lineWidth);
    _drawNode->setLocalZOrder(kDebugDrawLocalZOrder);
    _drawNode->setVisible(true);
}

void PhysicsDebugDraw::endDraw()
{
    if (_drawNode == nullptr)
    {
        return;
    }

    // nothing was requested for this frame, keep the node out of the render queue
    const bool anyOverlay = _config.drawShapes || _config.drawJoints || _config.drawContacts
        || _config.drawBoundingBoxes || _config.drawCentersOfMass || _config.drawVelocities
        || _config.drawSleepState;

    _drawNode->setVisible(anyOverlay);
}

void PhysicsDebugDraw::clear()
{
    if (_drawNode != nullptr)
    {
        _drawNode->clear();
    }
}

void PhysicsDebugDraw::drawWorld(PhysicsWorld* world)
{
    if (!_initialized || _drawNode == nullptr || world == nullptr)
    {
        return;
    }

    beginDraw();

    for (const auto& body : world->getAllBodies())
    {
        drawBody(body);
    }

    if (_config.drawJoints)
    {
        for (auto joint : world->_joints)
        {
            drawJoint(joint);
        }
    }

    endDraw();
}

void PhysicsDebugDraw::drawBody(PhysicsBody* body)
{
    if (_drawNode == nullptr || body == nullptr)
    {
        return;
    }

    const Vector<PhysicsShape*>& shapes = body->getShapes();

    if (_config.drawShapes)
    {
        for (const auto& shape : shapes)
        {
            drawShape(shape);
        }
    }

    if (_config.drawBoundingBoxes)
    {
        Vec2 lower;
        Vec2 upper;
        bool valid = false;

        for (const auto& shape : shapes)
        {
            const PhysicsShape::Type type = shape->getType();
            for (auto subShape : shape->_cpShapes)
            {
                switch (type)
                {
                    case PhysicsShape::Type::CIRCLE:
                    {
                        const float radius = PhysicsHelper::cpfloat2float(cpCircleShapeGetRadius(subShape));
                        const Vec2 centre = body->local2World(PhysicsHelper::cpv2point(cpCircleShapeGetOffset(subShape)));
                        expandBounds(centre - Vec2(radius, radius), lower, upper, valid);
                        expandBounds(centre + Vec2(radius, radius), lower, upper, valid);
                        break;
                    }
                    case PhysicsShape::Type::BOX:
                    case PhysicsShape::Type::POLYGON:
                    {
                        const int count = cpPolyShapeGetCount(subShape);
                        for (int i = 0; i < count; ++i)
                        {
                            expandBounds(body->local2World(PhysicsHelper::cpv2point(cpPolyShapeGetVert(subShape, i))),
                                         lower, upper, valid);
                        }
                        break;
                    }
                    case PhysicsShape::Type::EDGESEGMENT:
                    case PhysicsShape::Type::EDGEBOX:
                    case PhysicsShape::Type::EDGEPOLYGON:
                    case PhysicsShape::Type::EDGECHAIN:
                    {
                        expandBounds(body->local2World(PhysicsHelper::cpv2point(cpSegmentShapeGetA(subShape))),
                                     lower, upper, valid);
                        expandBounds(body->local2World(PhysicsHelper::cpv2point(cpSegmentShapeGetB(subShape))),
                                     lower, upper, valid);
                        break;
                    }
                    case PhysicsShape::Type::UNKNOWN:
                    default:
                        break;
                }
            }
        }

        if (valid)
        {
            drawBoundingBox(Rect(lower.x, lower.y, upper.x - lower.x, upper.y - lower.y), _config.bbColor);
        }
    }

    // the body local origin is its centre of gravity
    const Vec2 centerOfMass = body->local2World(Vec2::ZERO);

    if (_config.drawCentersOfMass)
    {
        drawCenterOfMass(centerOfMass, kCenterOfMassRadius, _config.contactColor);
    }

    if (_config.drawVelocities)
    {
        drawVelocityVector(centerOfMass, body->getVelocity(), _config.jointColor);
    }

    if (_config.drawSleepState)
    {
        drawSleepIndicator(centerOfMass, body->isResting(), _config.bbColor);
    }
}

void PhysicsDebugDraw::drawShape(PhysicsShape* shape)
{
    if (_drawNode == nullptr || shape == nullptr)
    {
        return;
    }

    PhysicsBody* body = shape->getBody();
    if (body == nullptr)
    {
        return;
    }

    const Color4F fillColor = getShapeColor(shape);
    const Color4F outlineColor(fillColor.r, fillColor.g, fillColor.b, 1.0f);
    const Color4F hollowColor(fillColor.r, fillColor.g, fillColor.b, 0.0f);
    const float angle = PhysicsHelper::cpfloat2float(cpBodyGetAngle(body->getCPBody()));

    switch (shape->getType())
    {
        case PhysicsShape::Type::CIRCLE:
        {
            for (auto subShape : shape->_cpShapes)
            {
                const float radius = PhysicsHelper::cpfloat2float(cpCircleShapeGetRadius(subShape));
                const Vec2 centre = body->local2World(PhysicsHelper::cpv2point(cpCircleShapeGetOffset(subShape)));
                drawCircleShape(centre, radius, angle, fillColor, outlineColor);
            }
            break;
        }
        case PhysicsShape::Type::BOX:
        case PhysicsShape::Type::POLYGON:
        {
            for (auto subShape : shape->_cpShapes)
            {
                const int count = cpPolyShapeGetCount(subShape);
                if (count < 2)
                {
                    continue;
                }

                std::vector<Vec2> verts(count);
                for (int i = 0; i < count; ++i)
                {
                    verts[i] = body->local2World(PhysicsHelper::cpv2point(cpPolyShapeGetVert(subShape, i)));
                }
                drawPolygonShape(verts.data(), count, fillColor, outlineColor);
            }
            break;
        }
        case PhysicsShape::Type::EDGEBOX:
        case PhysicsShape::Type::EDGEPOLYGON:
        {
            // one segment per edge, the begin points are the polygon loop
            const int count = static_cast<int>(shape->_cpShapes.size());
            if (count < 3)
            {
                break;
            }

            std::vector<Vec2> verts(count);
            for (int i = 0; i < count; ++i)
            {
                verts[i] = body->local2World(PhysicsHelper::cpv2point(cpSegmentShapeGetA(shape->_cpShapes[i])));
            }
            drawPolygonShape(verts.data(), count, hollowColor, outlineColor);
            break;
        }
        case PhysicsShape::Type::EDGESEGMENT:
        case PhysicsShape::Type::EDGECHAIN:
        {
            for (auto subShape : shape->_cpShapes)
            {
                const Vec2 a = body->local2World(PhysicsHelper::cpv2point(cpSegmentShapeGetA(subShape)));
                const Vec2 b = body->local2World(PhysicsHelper::cpv2point(cpSegmentShapeGetB(subShape)));
                drawSegmentShape(a, b, _config.lineWidth, outlineColor);
            }
            break;
        }
        case PhysicsShape::Type::UNKNOWN:
        default:
            break;
    }
}

void PhysicsDebugDraw::drawJoint(PhysicsJoint* joint)
{
    if (_drawNode == nullptr || joint == nullptr)
    {
        return;
    }

    PhysicsBody* bodyA = joint->getBodyA();
    PhysicsBody* bodyB = joint->getBodyB();
    if (bodyA == nullptr || bodyB == nullptr)
    {
        return;
    }

    const Color4F& color = _config.jointColor;

    auto spring = dynamic_cast<PhysicsJointSpring*>(joint);
    if (spring != nullptr)
    {
        drawSpringJoint(bodyA->local2World(spring->getAnchr1()),
                        bodyB->local2World(spring->getAnchr2()),
                        spring->getRestLength(), color);
        return;
    }

    auto limit = dynamic_cast<PhysicsJointLimit*>(joint);
    if (limit != nullptr)
    {
        drawSlideJoint(bodyA->local2World(limit->getAnchr1()),
                       bodyB->local2World(limit->getAnchr2()),
                       limit->getMin(), limit->getMax(), color);
        return;
    }

    auto groove = dynamic_cast<PhysicsJointGroove*>(joint);
    if (groove != nullptr)
    {
        const Vec2 grooveA = bodyA->local2World(groove->getGrooveA());
        const Vec2 grooveB = bodyA->local2World(groove->getGrooveB());
        const Vec2 anchr2 = bodyB->local2World(groove->getAnchr2());

        drawSlideJoint(grooveA, grooveB, 0.0f, grooveA.distance(grooveB), color);
        drawPinJoint(anchr2, grooveA, color);
        return;
    }

    // fixed, distance, pin and the rotary joints all pivot around the body origins
    drawPinJoint(bodyA->local2World(Vec2::ZERO), bodyB->local2World(Vec2::ZERO), color);
}

void PhysicsDebugDraw::drawCircleShape(const Vec2& center, float radius, float angle,
                                       const Color4F& fillColor, const Color4F& outlineColor)
{
    if (_drawNode == nullptr || radius <= 0.0f)
    {
        return;
    }

    Vec2 seg[kCircleSegments];
    for (int i = 0; i < kCircleSegments; ++i)
    {
        const float theta = angle + static_cast<float>(i) * kPi * 2.0f / static_cast<float>(kCircleSegments);
        seg[i] = center + Vec2(radius * std::cos(theta), radius * std::sin(theta));
    }

    _drawNode->drawPolygon(seg, kCircleSegments, fillColor, _config.lineWidth, outlineColor);
    // the spoke makes the rotation of the body visible
    _drawNode->drawLine(center, seg[0], outlineColor);
    _drawNode->drawDot(center, kCircleCenterDotRadius, outlineColor);
}

void PhysicsDebugDraw::drawPolygonShape(const Vec2* verts, int count,
                                        const Color4F& fillColor, const Color4F& outlineColor)
{
    if (_drawNode == nullptr || verts == nullptr || count < 2)
    {
        return;
    }

    if (count == 2)
    {
        drawSegmentShape(verts[0], verts[1], _config.lineWidth, outlineColor);
        return;
    }

    _drawNode->drawPolygon(verts, count, fillColor, _config.lineWidth, outlineColor);
}

void PhysicsDebugDraw::drawSegmentShape(const Vec2& a, const Vec2& b, float radius,
                                        const Color4F& color)
{
    if (_drawNode == nullptr)
    {
        return;
    }

    if (radius > 0.0f)
    {
        _drawNode->drawSegment(a, b, radius, color);
    }
    else
    {
        _drawNode->drawLine(a, b, color);
    }
}

void PhysicsDebugDraw::drawBoundingBox(const Rect& bb, const Color4F& color)
{
    if (_drawNode == nullptr)
    {
        return;
    }

    const Vec2 bottomLeft(bb.getMinX(), bb.getMinY());
    const Vec2 bottomRight(bb.getMaxX(), bb.getMinY());
    const Vec2 topRight(bb.getMaxX(), bb.getMaxY());
    const Vec2 topLeft(bb.getMinX(), bb.getMaxY());

    _drawNode->drawRect(bottomLeft, bottomRight, topRight, topLeft, color);
}

void PhysicsDebugDraw::drawContactPoint(const Vec2& point, const Vec2& normal, float depth,
                                        const Color4F& color)
{
    if (_drawNode == nullptr)
    {
        return;
    }

    _drawNode->drawDot(point, kJointAnchorRadius, color);

    if (normal.isZero())
    {
        return;
    }

    const float length = std::max(std::fabs(depth), kContactNormalMinLength);
    _drawNode->drawLine(point, point + normal.getNormalized() * length, color);
}

void PhysicsDebugDraw::drawVelocityVector(const Vec2& pos, const Vec2& vel, const Color4F& color)
{
    if (_drawNode == nullptr)
    {
        return;
    }

    const Vec2 delta = vel * kVelocityScale;
    if (delta.getLength() < kMinDrawLength)
    {
        return;
    }

    const Vec2 tip = pos + delta;
    const Vec2 dir = delta.getNormalized();
    const Vec2 back = tip - dir * kArrowHeadSize;
    const Vec2 side = dir.getPerp() * (kArrowHeadSize * 0.5f);

    _drawNode->drawLine(pos, tip, color);
    _drawNode->drawLine(tip, back + side, color);
    _drawNode->drawLine(tip, back - side, color);
}

void PhysicsDebugDraw::drawCenterOfMass(const Vec2& pos, float radius, const Color4F& color)
{
    if (_drawNode == nullptr)
    {
        return;
    }

    const float r = radius > 0.0f ? radius : kCenterOfMassRadius;

    _drawNode->drawDot(pos, r, color);
    _drawNode->drawLine(pos - Vec2(r * 2.0f, 0.0f), pos + Vec2(r * 2.0f, 0.0f), color);
    _drawNode->drawLine(pos - Vec2(0.0f, r * 2.0f), pos + Vec2(0.0f, r * 2.0f), color);
}

void PhysicsDebugDraw::drawSleepIndicator(const Vec2& pos, bool sleeping, const Color4F& color)
{
    if (_drawNode == nullptr)
    {
        return;
    }

    if (sleeping)
    {
        _drawNode->drawDot(pos, kSleepIndicatorRadius, color);
    }
    else
    {
        _drawNode->drawCircle(pos, kSleepIndicatorRadius, 0.0f, kSleepIndicatorSegments, false, color);
    }
}

void PhysicsDebugDraw::drawPinJoint(const Vec2& anchorA, const Vec2& anchorB, const Color4F& color)
{
    if (_drawNode == nullptr)
    {
        return;
    }

    _drawNode->drawLine(anchorA, anchorB, color);
    _drawNode->drawDot(anchorA, kJointAnchorRadius, color);
    _drawNode->drawDot(anchorB, kJointAnchorRadius, color);
}

void PhysicsDebugDraw::drawSpringJoint(const Vec2& anchorA, const Vec2& anchorB,
                                       float restLength, const Color4F& color)
{
    if (_drawNode == nullptr)
    {
        return;
    }

    _drawNode->drawDot(anchorA, kJointAnchorRadius, color);
    _drawNode->drawDot(anchorB, kJointAnchorRadius, color);

    const Vec2 delta = anchorB - anchorA;
    const float length = delta.getLength();
    if (length < kMinDrawLength)
    {
        return;
    }

    const Vec2 dir = delta.getNormalized();
    const Vec2 side = dir.getPerp() * kSpringCoilWidth;

    Vec2 previous = anchorA;
    for (int i = 1; i < kSpringCoilSegments; ++i)
    {
        const Vec2 onAxis = anchorA + dir * (length * static_cast<float>(i) / static_cast<float>(kSpringCoilSegments));
        const Vec2 next = (i % 2 == 0) ? onAxis - side : onAxis + side;
        _drawNode->drawLine(previous, next, color);
        previous = next;
    }
    _drawNode->drawLine(previous, anchorB, color);

    if (restLength > 0.0f)
    {
        // where the spring would settle along its own axis
        _drawNode->drawDot(anchorA + dir * std::min(restLength, length), kJointRestMarkRadius, color);
    }
}

void PhysicsDebugDraw::drawSlideJoint(const Vec2& anchorA, const Vec2& anchorB,
                                      float minDist, float maxDist, const Color4F& color)
{
    if (_drawNode == nullptr)
    {
        return;
    }

    _drawNode->drawLine(anchorA, anchorB, color);
    _drawNode->drawDot(anchorA, kJointAnchorRadius, color);
    _drawNode->drawDot(anchorB, kJointAnchorRadius, color);

    const Vec2 delta = anchorB - anchorA;
    const float length = delta.getLength();
    if (length < kMinDrawLength)
    {
        return;
    }

    const Vec2 dir = delta.getNormalized();
    const Vec2 tick = dir.getPerp() * kJointLimitTickSize;
    const Vec2 minPoint = anchorA + dir * minDist;
    const Vec2 maxPoint = anchorA + dir * maxDist;

    _drawNode->drawLine(minPoint - tick, minPoint + tick, color);
    _drawNode->drawLine(maxPoint - tick, maxPoint + tick, color);
}

Color4F PhysicsDebugDraw::getShapeColor(PhysicsShape* shape) const
{
    if (shape == nullptr)
    {
        return _config.shapeColor;
    }

    if (shape->isSensor())
    {
        const Color4F& base = _config.shapeColor;
        return Color4F(base.r, base.g, base.b, base.a * kSensorAlphaScale);
    }

    return getBodyColor(shape->getBody());
}

Color4F PhysicsDebugDraw::getBodyColor(PhysicsBody* body) const
{
    Color4F color = _config.shapeColor;
    if (body == nullptr)
    {
        return color;
    }

    float intensity = 1.0f;
    if (body->isResting())
    {
        intensity = kRestingIntensity;
    }
    else if (!body->isDynamic())
    {
        intensity = kStaticIntensity;
    }

    color.r *= intensity;
    color.g *= intensity;
    color.b *= intensity;

    return color;
}

